INSERT INTO ReguaPasso VALUES(1,'transacional',1,'Convite','imediato',NULL,'email,whatsapp',NULL,'Você foi convidado pra CCXP26','Olá, {{nome}}! {{host}} convidou você pra CCXP26 (03 a 06/dez, São Paulo Expo) com {{qtd}} ingresso(s): {{tipos}}. Complete seu cadastro pra receber os códigos: {{link}}',1);
INSERT INTO ReguaPasso VALUES(2,'transacional',2,'Lembrete de cadastro','D+3',NULL,'email,whatsapp','pular_se_cadastrado','Seus ingressos da CCXP26 esperam por você','{{nome}}, seus {{qtd}} ingresso(s) seguem reservados, mas o cadastro ainda não foi concluído. Leva 1 minuto: {{link}}',1);
INSERT INTO ReguaPasso VALUES(3,'transacional',3,'Aviso de expiração','D+6',NULL,'email,whatsapp','pular_se_cadastrado','Último dia: seu convite expira amanhã','{{nome}}, seu convite pra CCXP26 expira amanhã e os ingressos voltam ao pool. Garanta os seus: {{link}}',1);
INSERT INTO ReguaPasso VALUES(4,'transacional',4,'Instrução de resgate','após cadastro',NULL,'email',NULL,'Como resgatar seus ingressos na Mundo Ticket','{{nome}}, seus códigos estão na sua carteira. Resgate na Mundo Ticket com o passo a passo: {{link}}. Qualquer dúvida, fale com {{host}}.',1);
INSERT INTO ReguaPasso VALUES(5,'regua',1,'Falta uma semana','D-7','2026-11-26','email',NULL,'Falta uma semana pra CCXP26','{{nome}}, em 7 dias a CCXP26 abre os portões no São Paulo Expo. Como chegar, por onde entrar e o que levar: tudo neste guia. Seus ingressos: {{tipos}}.',1);
INSERT INTO ReguaPasso VALUES(6,'regua',2,'Lembrete de resgate','D-3','2026-11-30','email,whatsapp','pular_se_resgatado','Já resgatou seus ingressos?','{{nome}}, faltam 3 dias e seus códigos ainda não foram resgatados na Mundo Ticket. Resolve agora em 2 minutos: {{link}}. Mapa do evento em anexo.',1);
INSERT INTO ReguaPasso VALUES(7,'regua',3,'Véspera: agenda do dia','D-1','2026-12-02','email',NULL,'Amanhã tem CCXP26: sua agenda','{{nome}}, amanhã começa! Agenda do dia, dicas práticas e o lounge VIP Omelete te esperando. Credenciamento VIP abre 1h antes dos portões.',1);
INSERT INTO ReguaPasso VALUES(8,'regua',4,'É hoje','Dia 1','2026-12-03','whatsapp',NULL,'É hoje! CCXP26 abre às 12h','{{nome}}, chegou o dia. Destaques de hoje no Palco Thunder, entrada VIP pela entrada Sul. Bom evento!',1);
